use super::*;
use tokio::{net::{TcpListener,TcpStream,UdpSocket},sync::oneshot};
use crate::app::remote_content_manager::providers::rule_provider::{mobile_make_rules,mobile_rules_mrs_parse,RuleSetBehavior};
fn question()->Message {let mut message=Message::query();message.metadata.id=91;let mut query=Query::new();query.set_name(Name::from_str_relaxed("native-dns.test").unwrap());query.set_query_type(RecordType::A);message.add_query(query);message}
fn answer(message:&Message)->Message{let mut result=Message::response(message.metadata.id,message.metadata.op_code);result.queries=message.queries.clone();result.add_answer(hickory_proto::rr::Record::from_rdata(message.queries[0].name().clone(),60,RData::A(hickory_proto::rr::rdata::A("192.0.2.81".parse().unwrap()))));result}
pub(crate) async fn typed(){
    let original=question();assert!(!original.queries[0].name().is_fqdn());let wire=Message::from_vec(&answer(&original).to_vec().unwrap()).unwrap();assert!(wire.queries[0].name().is_fqdn());check_response(&original,&wire).unwrap();
    let mut wrong=wire.clone();wrong.queries[0].set_query_type(RecordType::AAAA);assert!(check_response(&original,&wrong).is_err());
    let mut wrong=wire.clone();wrong.queries[0].set_name(Name::from_str_relaxed("other.test.").unwrap());assert!(check_response(&original,&wrong).is_err());
    let mut wrong=wire.clone();wrong.queries[0].set_query_class(hickory_proto::rr::DNSClass::CH);assert!(check_response(&original,&wrong).is_err());
    let mut wrong=wire.clone();wrong.metadata.id=wrong.metadata.id.wrapping_add(1);assert!(check_response(&original,&wrong).is_err());

    let snapshot:dns_network::NetworkDns=serde_json::from_str(r#"{"defaultInterface":"wlan0","interfaces":{"wlan0":["192.0.2.53","fe80::1%wlan0"]}}"#).unwrap();snapshot.validate().unwrap();assert!(snapshot.servers(Some("missing0")).is_err());
    for json in [r#"{"defaultInterface":"absent","interfaces":{}}"#,r#"{"defaultInterface":null,"interfaces":{"wlan0":["0.0.0.0"]}}"#,r#"{"defaultInterface":null,"interfaces":{"wlan0":["fe80::1%other0"]}}"#,r#"{"defaultInterface":null,"interfaces":{"wlan0":["1.2.3.4%wlan0"]}}"#] {assert!(serde_json::from_str::<dns_network::NetworkDns>(json).unwrap().validate().is_err());}
    assert!(serde_json::from_str::<dns_network::NetworkDns>(r#"{"defaultInterface":null,"interfaces":{"wlan0":["resolver.test"]}}"#).unwrap().validate().is_err());
    let empty=dns_network::NetworkDns::default();empty.validate().unwrap();assert!(empty.servers(None).is_err());
    let config=parse("dns: {enable: true, nameserver: [system,'dhcp://wlan0']}\n").unwrap();assert_eq!(config.dns.nameserver.len(),2);assert!(dns_network::validate_runtime(&config).is_err());
    let context=context().unwrap();*context.network_dns.write().unwrap()=Some(empty);assert!(dns_network::exchange(None,&question()).await.is_err());
}
pub(crate) async fn io(fail:bool){
    let upstream=UdpSocket::bind("127.0.0.1:0").await.unwrap();let upstream_address=upstream.local_addr().unwrap();let source_task=tokio::spawn(async move {let mut bytes=[0;4096];loop {let (n,peer)=upstream.recv_from(&mut bytes).await.unwrap();let message=Message::from_vec(&bytes[..n]).unwrap();upstream.send_to(&answer(&message).to_vec().unwrap(),peer).await.unwrap();}});
    let held:Vec<_>=(26000..49151).filter_map(|p|{let tcp=std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,p)).ok()?;let udp=std::net::UdpSocket::bind((std::net::Ipv4Addr::LOCALHOST,p)).ok()?;Some((tcp,udp))}).take(3).collect();let ports:Vec<_>=held.iter().map(|(s,_)|s.local_addr().unwrap().port()).collect();drop(held);
    let source=format!("mode: direct\nmmdb: null\nasn-mmdb: null\ngeosite: null\ntun: {{enable: false}}\ndns: {{enable: true, listen: {{udp: '127.0.0.1:{}', tcp: '127.0.0.1:{}'}}, nameserver: ['udp://{upstream_address}'], default-nameserver: ['udp://{upstream_address}']}}\nmixed-port: {}\nallow-lan: false\nbind-address: 127.0.0.1\nexternal-controller: 127.0.0.1:{}\nsecret: '0123456789abcdef0123456789abcdef'\ncors-allow-origins: []\nrules: ['MATCH,DIRECT']\n",ports[2],ports[2],ports[0],ports[1]);
    let directory=tempfile::tempdir().unwrap();let cancel=CancellationToken::new();let stop=cancel.clone();let control=runtime_control::RuntimeControl::new();let owner_control=control.clone();let (ready,rx)=oneshot::channel();let owner=tokio::spawn(run_runtime_control(source,directory.path().to_owned(),RuntimeInput::Proxy,stop,owner_control,move|info|{let _=ready.send(info);}));tokio::time::timeout(Duration::from_secs(5),rx).await.unwrap().unwrap();
    let message=question();let response=query_exchange(&message,format!("127.0.0.1:{}",ports[2]).parse().unwrap()).await.unwrap();assert_eq!(response.answers.len(),1);
    let mut stream=TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,ports[2])).await.unwrap();let bytes=message.to_vec().unwrap();stream.write_u16(bytes.len() as u16).await.unwrap();stream.write_all(&bytes).await.unwrap();let n=stream.read_u16().await.unwrap() as usize;let mut bytes=vec![0;n];stream.read_exact(&mut bytes).await.unwrap();assert_eq!(Message::from_vec(&bytes).unwrap().answers.len(),1);drop(stream);
    let ctl=control.clone();let status=tokio::task::spawn_blocking(move||ctl.park()).await.unwrap().unwrap();assert!(!status.listening&&status.active_ports.is_empty());
    let tcp=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,ports[2])).await.unwrap();let udp=UdpSocket::bind((std::net::Ipv4Addr::LOCALHOST,ports[2])).await.unwrap();drop(tcp);
    if fail {let ctl=control.clone();assert!(tokio::task::spawn_blocking(move||ctl.resume_proxy()).await.unwrap().is_err());assert!(tokio::time::timeout(Duration::from_secs(5),owner).await.unwrap().unwrap().is_err());}
    else {drop(udp);let ctl=control.clone();assert!(tokio::task::spawn_blocking(move||ctl.resume_proxy()).await.unwrap().unwrap().listening);let response=query_exchange(&message,format!("127.0.0.1:{}",ports[2]).parse().unwrap()).await.unwrap();assert_eq!(response.answers.len(),1);cancel.cancel();tokio::time::timeout(Duration::from_secs(5),owner).await.unwrap().unwrap().unwrap();}
    source_task.abort();let _=source_task.await;assert!(TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,ports[2])).await.is_ok());
}
pub(crate) async fn rules(){
    let raw:Vec<_>=(0..1201).map(|i|format!("host{i}.example")).collect();let content=mobile_make_rules(RuleSetBehavior::Domain,raw.clone(),None,None).unwrap();let first=content.page(0,500);assert_eq!(first.rule_count,1201);assert_eq!(first.rules.len(),500);assert_eq!(first.next_offset,Some(500));assert!(!first.complete);let mut rows=first.rules;rows.extend(content.page(500,500).rules);let last=content.page(1000,500);assert!(last.complete);rows.extend(last.rules);rows.sort();let mut expected=raw;expected.sort();assert_eq!(rows,expected);
    let cidr=mobile_make_rules(RuleSetBehavior::Ipcidr,vec!["192.0.2.81/24".into(),"2001:db8::1/32".into()],None,None).unwrap().page(0,100);assert_eq!(cidr.rule_count,2);assert!(cidr.rules.contains(&"192.0.2.0/24".into()));assert!(cidr.rules.contains(&"2001:db8::/32".into()));
    let labels=b"moc.elpmaxe";let mut bytes=b"MRS\x01\x00".to_vec();bytes.extend_from_slice(&1i64.to_be_bytes());bytes.extend_from_slice(&0i64.to_be_bytes());bytes.push(1);bytes.extend_from_slice(&1i64.to_be_bytes());bytes.extend_from_slice(&(1u64<<labels.len()).to_be_bytes());bytes.extend_from_slice(&1i64.to_be_bytes());let mut bitmap=0u64;for i in 0..labels.len(){bitmap|=1<<(i*2+1);}bitmap|=1<<(labels.len()*2);bytes.extend_from_slice(&bitmap.to_be_bytes());bytes.extend_from_slice(&(labels.len() as i64).to_be_bytes());bytes.extend_from_slice(labels);let packed=zstd::encode_all(bytes.as_slice(),1).unwrap();let page=mobile_rules_mrs_parse(&packed,RuleSetBehavior::Domain).unwrap().page(0,500);assert_eq!(page.rule_count,1);assert_eq!(page.rules,vec!["example.com"]);
    let mut bytes=b"MRS\x01\x01".to_vec();bytes.extend_from_slice(&1i64.to_be_bytes());bytes.extend_from_slice(&0i64.to_be_bytes());bytes.push(1);bytes.extend_from_slice(&1i64.to_be_bytes());bytes.extend_from_slice(&"192.0.2.0".parse::<std::net::Ipv4Addr>().unwrap().to_ipv6_mapped().octets());bytes.extend_from_slice(&"192.0.2.255".parse::<std::net::Ipv4Addr>().unwrap().to_ipv6_mapped().octets());let packed=zstd::encode_all(bytes.as_slice(),1).unwrap();let page=mobile_rules_mrs_parse(&packed,RuleSetBehavior::Ipcidr).unwrap().page(0,500);assert_eq!(page.rule_count,1);assert_eq!(page.rules,vec!["192.0.2.0/24"]);
}
